"""A stepped load shape for lab qec04, step 4. You do not edit this file.

Five stages of rising users, 60 seconds each (5 minutes in all). Locust reads it when you list it after your
locustfile:    locust -f locustfile.py,stepped_shape.py --host http://localhost:8080

While a shape is active, Locust sets the number of users itself: the user and spawn-rate boxes in the web
page do not matter.
"""
from locust import LoadTestShape

STAGES = [(60, 10), (120, 20), (180, 30), (240, 40), (300, 50)]   # (run time in seconds when the stage ends, users)
SPAWN_RATE = 5   # new users per second when a stage starts


class SteppedShape(LoadTestShape):
    def tick(self):
        run_time = self.get_run_time()
        for ends_at, users in STAGES:
            if run_time < ends_at:
                return users, SPAWN_RATE
        return None   # the run stops after the last stage
